    if(a==='set'&&v&&v.startsWith('mode:')){const m=v.slice(5);if(!mapOk(m,CFG.map)){CFG.map=mapsFor(m)[0]||'q7';loadMapUI(CFG.map).then(()=>{if(UI.open==='setup')UI.buildSetup()})}}
